import {
  $getSelection,
  $isRangeSelection,
  COMMAND_PRIORITY_EDITOR,
  type LexicalCommand,
  type LexicalEditor,
  REDO_COMMAND,
  type RangeSelection,
  UNDO_COMMAND,
