import { useCallback, useEffect, useRef, useState } from "react";

import {
  $getNearestNodeFromDOMNode,
  $getNodeByKey,
  $getRoot,
  $getSelection,
  $isDecoratorNode,
  $isNodeSelection,
  COPY_COMMAND,
  CUT_COMMAND,
  PASTE_COMMAND,
  registerEventListener,
} from "lexical";

import { $isAutoLinkNode, $isLinkNode } from "@lexical/link";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";

import {
  ClipboardDocumentIcon,
  ClipboardIcon,
  DocumentDuplicateIcon,
  LinkSlashIcon,
  ScissorsIcon,
  TrashIcon,
} from "@heroicons/react/16/solid";
import { Button } from "react-aria-components/Button";

import { Menu, MenuItem, MenuSeparator, MenuTrigger } from "@/components/ui/menu";

export function ContextMenuPlugin() {
  const [editor] = useLexicalComposerContext();
  const triggerRef = useRef<HTMLButtonElement>(null);
  const [target, setTarget] = useState<{ key: string; isLink: boolean } | null>(null);

  useEffect(() => {
    function onContextMenu(event: MouseEvent) {
      const trigger = triggerRef.current;
      if (trigger === null || !(event.target instanceof Node)) {
        return;
      }
      event.preventDefault();
      trigger.style.left = `${event.clientX}px`;
      trigger.style.top = `${event.clientY}px`;
      editor.read(() => {
        const node = $getNearestNodeFromDOMNode(event.target as Node) ?? $getRoot();
        setTarget({
          key: node.getKey(),
          isLink: $isLinkNode(node) || $isLinkNode(node.getParent()),
        });
      });
      trigger.dispatchEvent(
        new MouseEvent("contextmenu", {
          bubbles: true,
          cancelable: true,
          clientX: event.clientX,
          clientY: event.clientY,
        }),
      );
    }

    return editor.registerRootListener((rootElement) => {
      if (rootElement !== null) {
        return registerEventListener(rootElement, "contextmenu", onContextMenu);
      }
    });
  }, [editor]);

  const removeLink = useCallback(() => {
    if (target === null) {
      return;
    }
    editor.update(() => {
      const node = $getNodeByKey(target.key);
      const parent = node?.getParent();
      const link = $isLinkNode(node) ? node : $isLinkNode(parent) ? parent : null;
      if (link === null) {
        return;
      }
      if ($isAutoLinkNode(link)) {
        link.setIsUnlinked(true);
        return;
      }
      for (const child of link.getChildren()) {
        link.insertBefore(child);
      }
      link.remove();
    });
  }, [editor, target]);

  const pasteFromClipboard = useCallback(
    async (plainText: boolean) => {
      try {
        const data = new DataTransfer();
        if (plainText) {
          data.setData("text/plain", await navigator.clipboard.readText());
        } else {
          const [item] = await navigator.clipboard.read();
          for (const type of item.types) {
            data.setData(type, await (await item.getType(type)).text());
          }
        }
        editor.dispatchCommand(PASTE_COMMAND, new ClipboardEvent("paste", { clipboardData: data }));
      } catch {
        window.alert("Clipboard access is not allowed");
      }
    },
    [editor],
  );

  const deleteNode = useCallback(() => {
    editor.update(() => {
      const selection = $getSelection();
      if ($isNodeSelection(selection)) {
        for (const node of selection.getNodes()) {
          if ($isDecoratorNode(node)) {
            node.remove();
          }
        }
        return;
      }
      const node = target === null ? null : $getNodeByKey(target.key);
      if (node === null) {
        return;
      }
      if ($isDecoratorNode(node)) {
        node.remove();
      } else {
        node.getTopLevelElement()?.remove();
      }
    });
  }, [editor, target]);

  return (
    <MenuTrigger trigger="contextMenu">
      <span aria-hidden="true" className="contents">
        <Button
          ref={triggerRef}
          excludeFromTabOrder
          className="pointer-events-none fixed size-0 opacity-0"
        />
      </span>
      <Menu className="w-52">
        {target?.isLink && (
          <>
            <MenuItem onAction={removeLink}>
              <LinkSlashIcon />
              Remove link
            </MenuItem>
            <MenuSeparator />
          </>
        )}
        <MenuItem onAction={() => editor.dispatchCommand(CUT_COMMAND, null)}>
          <ScissorsIcon />
          Cut
        </MenuItem>
        <MenuItem onAction={() => editor.dispatchCommand(COPY_COMMAND, null)}>
          <DocumentDuplicateIcon />
          Copy
        </MenuItem>
        <MenuItem onAction={() => pasteFromClipboard(false)}>
          <ClipboardIcon />
          Paste
        </MenuItem>
        <MenuItem onAction={() => pasteFromClipboard(true)}>
          <ClipboardDocumentIcon />
          Paste as plain text
        </MenuItem>
        <MenuSeparator />
        <MenuItem intent="danger" onAction={deleteNode}>
          <TrashIcon />
          Delete
        </MenuItem>
      </Menu>
    </MenuTrigger>
  );
}

import { useEffect, useRef, useState } from "react";

import {
  $createParagraphNode,
  $createTextNode,
  $getNearestNodeFromDOMNode,
  $isElementNode,
} from "lexical";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { DraggableBlockPlugin_EXPERIMENTAL } from "@lexical/react/LexicalDraggableBlockPlugin";

import { EllipsisVerticalIcon, PlusIcon } from "@heroicons/react/16/solid";
import { twMerge } from "cn";
import type { PressEvent } from "react-aria-components/Button";

import { Button } from "@/components/ui/button";

const DRAGGABLE_BLOCK_MENU_CLASSNAME = "draggable-block-menu";

function isOnMenu(element: HTMLElement): boolean {
  return !!element.closest(`.${DRAGGABLE_BLOCK_MENU_CLASSNAME}`);
}

export function DraggableBlockPlugin() {
  const [editor] = useLexicalComposerContext();
  const menuRef = useRef<HTMLDivElement>(null);
  const targetLineRef = useRef<HTMLDivElement>(null);
  const [draggableElement, setDraggableElement] = useState<HTMLElement | null>(null);
  const [anchorElem, setAnchorElem] = useState<HTMLElement | null>(null);

  useEffect(() => {
    return editor.registerRootListener((rootElement) => {
      setAnchorElem(rootElement?.parentElement ?? null);
    });
  }, [editor]);

  if (!anchorElem) {
    return null;
  }

  function insertSlashBlock(event: PressEvent) {
    if (!draggableElement) {
      return;
    }
    editor.update(() => {
      const node = $getNearestNodeFromDOMNode(draggableElement);
      if (!node) {
        return;
      }
      if ($isElementNode(node)) {
        const textContent = node.getTextContent();
        const needsSpace = textContent !== "" && !/\s$/.test(textContent);
        node.selectEnd().insertText(needsSpace ? " /" : "/");
        return;
      }
      const paragraph = $createParagraphNode();
      const textNode = $createTextNode("/");
      paragraph.append(textNode);
      if (event.altKey || event.ctrlKey) {
        node.insertBefore(paragraph);
      } else {
        node.insertAfter(paragraph);
      }
      textNode.selectEnd();
    });
    editor.focus();
  }

  return (
    <DraggableBlockPlugin_EXPERIMENTAL
      anchorElem={anchorElem}
      menuRef={menuRef}
      targetLineRef={targetLineRef}
      menuComponent={
        <div
          ref={menuRef}
          className={twMerge(
            DRAGGABLE_BLOCK_MENU_CLASSNAME,
            "absolute top-0 flex cursor-grab items-center rounded-md p-px opacity-0 will-change-transform active:cursor-grabbing",
            "left-0",
          )}
        >
          <Button
            intent="plain"
            size="sq-xs"
            aria-label="Click to open block menu"
            className="size-5 rounded-sm before:hidden! sm:size-5"
            preventFocusOnPress
            onPress={insertSlashBlock}
          >
            <PlusIcon />
          </Button>
          <div className="flex size-5 items-center justify-center rounded-sm text-muted-foreground hover:bg-secondary hover:text-secondary-foreground">
            <EllipsisVerticalIcon className="size-4" />
          </div>
        </div>
      }
      targetLineComponent={
        <div
          ref={targetLineRef}
          className="pointer-events-none absolute top-0 left-0 h-1 rounded-full bg-primary/50 opacity-0 will-change-transform"
        />
      }
      isOnMenu={isOnMenu}
      onElementChanged={setDraggableElement}
    />
  );
}

