function FloatingToolbar({
  editor,
  children,
  ref,
}: {
  editor: LexicalEditor;
  children: React.ReactNode;
  ref?: React.Ref<HTMLDivElement | null>;
}) {
  const triggerRef = useRef<HTMLSpanElement | null>(null);
  const popupRef = useRef<HTMLDivElement | null>(null);

  const setPopupRefs = useCallback(
    (elem: HTMLDivElement | null) => {
      popupRef.current = elem;
      if (typeof ref === "function") {
        ref(elem);
      } else if (ref) {
        ref.current = elem;
      }
    },
    [ref],
  );

  useEffect(() => {
    function mouseMoveListener(e: MouseEvent) {
      const popupElem = popupRef.current;
      if (popupElem && (e.buttons === 1 || e.buttons === 3)) {
        if (popupElem.style.pointerEvents !== "none") {
          const popupRoot = popupElem.getRootNode();
          const elementUnderMouse =
            isDOMDocumentNode(popupRoot) || isDOMShadowRoot(popupRoot)
              ? popupRoot.elementFromPoint(e.clientX, e.clientY)
              : null;
          if (!popupElem.contains(elementUnderMouse)) {
            popupElem.style.pointerEvents = "none";
          }
        }
      }
    }
    function mouseUpListener() {
      const popupElem = popupRef.current;
      if (popupElem && popupElem.style.pointerEvents !== "auto") {
        popupElem.style.pointerEvents = "auto";
      }
    }
    return registerEventListeners(document, {
      mousemove: mouseMoveListener,
      mouseup: mouseUpListener,
    });
  }, []);

  const $updateAnchorPosition = useCallback(() => {
    const triggerElem = triggerRef.current;
    if (triggerElem === null) {
      return;
    }

    const selection = $getSelection();
    const nativeSelection = getDOMSelection(editor._window);
    const rootElement = editor.getRootElement();
    let targetRect: DOMRect | null = null;

    if ($isRangeSelection(selection) && nativeSelection !== null && rootElement !== null) {
      const points = getDOMSelectionPoints(nativeSelection, rootElement);
      const pointsCollapsed =
        points.anchorNode === points.focusNode && points.anchorOffset === points.focusOffset;
      if (!pointsCollapsed && rootElement.contains(points.anchorNode)) {
        targetRect = getDOMRangeRect(nativeSelection, rootElement);
      }
    }

    if (targetRect !== null) {
      setFloatingAnchorRect(triggerElem, targetRect);
    } else {
      hideFloatingAnchor(triggerElem);
    }
  }, [editor]);

  useEffect(() => {
    const update = () => {
      editor.read("latest", () => {
        $updateAnchorPosition();
      });
    };

    return mergeRegister(
      registerEventListener(window, "resize", update),
      registerEventListener(document, "scroll", update, true),
      registerEventListener(document, "selectionchange", update),
    );
  }, [editor, $updateAnchorPosition]);

  useEffect(() => {
    editor.read("latest", () => {
      $updateAnchorPosition();
    });
    return mergeRegister(
      editor.registerUpdateListener(({ editorState }) => {
        editorState.read(() => {
          $updateAnchorPosition();
        });
      }),
      editor.registerCommand(
        SELECTION_CHANGE_COMMAND,
        () => {
          $updateAnchorPosition();
          return false;
        },
        COMMAND_PRIORITY_LOW,
      ),
    );
  }, [editor, $updateAnchorPosition]);

  return (
    <>
      <span
        ref={triggerRef}
        aria-hidden="true"
        className="pointer-events-none fixed top-0 left-0 opacity-0"
        style={{ transform: "translate(-10000px, -10000px)" }}
      />
      <Popover
        ref={setPopupRefs}
        isOpen
        isNonModal
        triggerRef={triggerRef}
        placement="top start"
        offset={8}
        className="w-auto min-w-0 max-w-[min(36rem,calc(100vw-2rem))]"
      >
        <Toolbar
          aria-label="Text formatting"
          className="w-full flex-wrap gap-1 overflow-hidden bg-transparent p-1 inset-ring-0"
        >
          {children}
        </Toolbar>
      </Popover>
    </>
  );
}

function useIsTextSelected(editor: LexicalEditor): boolean {
  const [isText, setIsText] = useState(false);

  const updatePopup = useCallback(() => {
    editor.read("latest", () => {
      if (editor.isComposing()) {
        return;
      }
      const selection = $getSelection();
      const nativeSelection = getDOMSelection(editor._window);
      const rootElement = editor.getRootElement();

      if (
        nativeSelection !== null &&
        (!$isRangeSelection(selection) ||
          rootElement === null ||
          !rootElement.contains(getDOMSelectionPoints(nativeSelection, rootElement).anchorNode))
      ) {
        setIsText(false);
        return;
      }

      if (!$isRangeSelection(selection)) {
        return;
      }

      const rawTextContent = selection.getTextContent().replace(/\n/g, "");
      if (selection.isCollapsed() || rawTextContent === "") {
        setIsText(false);
        return;
      }

      const node = $getSelectedNode(selection);
      setIsText($isTextNode(node) || $isParagraphNode(node));
    });
  }, [editor]);

  useEffect(() => {
    return registerEventListener(document, "selectionchange", updatePopup);
  }, [updatePopup]);

  useEffect(() => {
    return mergeRegister(
      editor.registerUpdateListener(() => {
        updatePopup();
      }),
      editor.registerRootListener(() => {
        if (editor.getRootElement() === null) {
          setIsText(false);
        }
      }),
    );
  }, [editor, updatePopup]);

  return isText;
}

export function FloatingToolbarPlugin({ children }: { children?: React.ReactNode }) {
  const [editor] = useLexicalComposerContext();
  const isEditable = useLexicalEditable();
  const isText = useIsTextSelected(editor);

  const toolbarRef = useRef<HTMLDivElement | null>(null);
  useEffect(() => {
    const onDragStart = () => {
      if (toolbarRef.current) {
        toolbarRef.current.style.display = "none";
      }
    };
    const onDragEnd = () => {
      if (toolbarRef.current && toolbarRef.current.style.display === "none") {
        toolbarRef.current.style.display = "";
      }
    };
    return registerEventListeners(
      document,
      { dragend: onDragEnd, dragstart: onDragStart, drop: onDragEnd },
      true,
    );
  }, []);

  if (!isEditable || !isText) {
    return null;
  }

  return (
    <FloatingToolbar editor={editor} ref={toolbarRef}>
      {children}
    </FloatingToolbar>
  );
}

import { getDOMSelectionRangeAndPoints } from "lexical";

export function getDOMRangeRect(nativeSelection: Selection, rootElement: HTMLElement): DOMRect {
  const { points, range } = getDOMSelectionRangeAndPoints(nativeSelection, rootElement);
  if (points.anchorNode === rootElement || range === null) {
    let inner = rootElement;
    while (inner.firstElementChild != null) {
      inner = inner.firstElementChild as HTMLElement;
    }
    return inner.getBoundingClientRect();
  }
  return range.getBoundingClientRect();
}

export function setFloatingAnchorRect(floatingAnchor: HTMLElement, targetRect: DOMRect): void {
  floatingAnchor.style.transform = `translate(${targetRect.left}px, ${targetRect.top}px)`;
  floatingAnchor.style.width = `${targetRect.width}px`;
  floatingAnchor.style.height = `${targetRect.height}px`;
}

export function hideFloatingAnchor(floatingAnchor: HTMLElement): void {
  floatingAnchor.style.transform = "translate(-10000px, -10000px)";
}

