type ActionsPosition = { x: number; y: number; canDelete: boolean };

const BUTTON_CLASSNAME = "size-5 rounded-sm bg-overlay shadow-sm sm:size-5";
const DELETE_BUTTON_CLASSNAME = `${BUTTON_CLASSNAME} hover:*:[svg]:text-danger`;

function getCellSelector(theme: EditorThemeClasses | null | undefined): string {
  const cellClassName = theme?.tableCell?.split(/\s+/)[0];
  return cellClassName ? `td.${cellClassName}, th.${cellClassName}` : "td, th";
}

function getColumnCount(tableElement: HTMLTableElement): number {
  const firstRow = tableElement.rows[0];
  if (!firstRow) {
    return 0;
  }
  return Array.from(firstRow.cells).reduce((count, cell) => count + cell.colSpan, 0);
}

function getClosestTopCell(
  tableElement: HTMLTableElement,
  clientX: number,
): HTMLTableCellElement | null {
  const firstRow = tableElement.rows[0];
  if (!firstRow) {
    return null;
  }

  let closest: HTMLTableCellElement | null = null;
  let smallestDelta = Number.POSITIVE_INFINITY;

  for (const cell of Array.from(firstRow.cells)) {
    const rect = cell.getBoundingClientRect();
    const delta = Math.abs(rect.left + rect.width / 2 - clientX);
    if (delta < smallestDelta) {
      smallestDelta = delta;
      closest = cell;
    }
  }

  return closest;
}

export function TableHoverActionsPlugin() {
  const [editor, { getTheme }] = useLexicalComposerContext();
  const isEditable = useLexicalEditable();
  const [columnPosition, setColumnPosition] = useState<ActionsPosition | null>(null);
  const [rowPosition, setRowPosition] = useState<ActionsPosition | null>(null);
  const columnActionsRef = useRef<HTMLDivElement | null>(null);
  const rowActionsRef = useRef<HTMLDivElement | null>(null);
  const columnCellRef = useRef<HTMLTableCellElement | null>(null);
  const rowCellRef = useRef<HTMLTableCellElement | null>(null);

  const hideActions = useCallback(() => {
    columnCellRef.current = null;
    rowCellRef.current = null;
    setColumnPosition(null);
    setRowPosition(null);
  }, []);

  const updatePositions = useCallback(() => {
    const columnCell = columnCellRef.current;
    const columnTable = columnCell?.closest("table") ?? null;
    if (columnCell?.isConnected && columnTable) {
      const rect = columnCell.getBoundingClientRect();
      setColumnPosition({
        x: rect.left + rect.width / 2,
        y: columnTable.getBoundingClientRect().top,
        canDelete: getColumnCount(columnTable) > 1,
      });
    } else {
      columnCellRef.current = null;
      setColumnPosition(null);
    }

    const rowCell = rowCellRef.current;
    const rowTable = rowCell?.closest("table") ?? null;
    if (rowCell?.isConnected && rowTable) {
      const rect = rowCell.getBoundingClientRect();
      const tableRect = rowTable.getBoundingClientRect();
      const isRTL = getComputedStyle(rowTable).direction === "rtl";
      setRowPosition({
        x: isRTL ? tableRect.right : tableRect.left,
        y: rect.top + rect.height / 2,
        canDelete: rowTable.rows.length > 1,
      });
    } else {
      rowCellRef.current = null;
      setRowPosition(null);
    }
  }, []);

  useEffect(() => {
    if (!isEditable) {
      return;
    }

    const handleMouseMove = (event: MouseEvent) => {
      const target = getComposedEventTarget(event);
      if (!isHTMLElement(target)) {
        return;
      }
      if (columnActionsRef.current?.contains(target) || rowActionsRef.current?.contains(target)) {
        return;
      }

      const cell = target.closest<HTMLTableCellElement>(getCellSelector(getTheme()));
      const tableElement = cell?.closest("table") ?? null;
      const rootElement = editor.getRootElement();

      if (
        !cell ||
        tableElement === null ||
        rootElement === null ||
        !rootElement.contains(tableElement)
      ) {
        hideActions();
        return;
      }

      const rowIndex = isHTMLTableRowElement(cell.parentElement) ? cell.parentElement.rowIndex : -1;
      columnCellRef.current =
        rowIndex === 0 ? getClosestTopCell(tableElement, event.clientX) : null;
      rowCellRef.current = cell.cellIndex === 0 ? cell : null;
      updatePositions();
    };

    return mergeRegister(
      registerEventListener(document, "mousemove", handleMouseMove),
      hideActions,
    );
  }, [editor, getTheme, hideActions, isEditable, updatePositions]);

  useEffect(() => {
    if (!isEditable) {
      return;
    }

    const handleMouseLeave = (event: MouseEvent) => {
      const nextTarget = event.relatedTarget;
      if (
        nextTarget instanceof Node &&
        (columnActionsRef.current?.contains(nextTarget) ||
          rowActionsRef.current?.contains(nextTarget))
      ) {
        return;
      }
      hideActions();
    };

    return editor.registerRootListener((rootElement) => {
      if (rootElement) {
        return registerEventListener(rootElement, "mouseleave", handleMouseLeave);
      }
    });
  }, [editor, hideActions, isEditable]);

  useEffect(() => {
    return mergeRegister(
      registerEventListener(window, "resize", updatePositions),
      registerEventListener(document, "scroll", updatePositions, true),
      editor.registerUpdateListener(updatePositions),
    );
  }, [editor, updatePositions]);

  const withCell = (cellRef: React.RefObject<HTMLTableCellElement | null>, $action: () => void) => {
    const cell = cellRef.current;
    if (!cell) {
      return;
    }
    editor.update(() => {
      const node = $getNearestNodeFromDOMNode(cell);
      if ($isTableCellNode(node)) {
        node.selectEnd();
        $action();
      }
    });
  };

  if (!isEditable || typeof document === "undefined") {
    return null;
  }

  return createPortal(
    <>
      {columnPosition ? (
        <div
          ref={columnActionsRef}
          className="fixed z-10 flex -translate-x-1/2 -translate-y-1/2 items-center gap-0.5"
          style={{ left: columnPosition.x, top: columnPosition.y }}
        >
          <TooltipTrigger>
            <Button
              intent="outline"
              size="sq-xs"
              aria-label="Add column"
              className={BUTTON_CLASSNAME}
              preventFocusOnPress
              onPress={() => withCell(columnCellRef, $insertTableColumnAtSelection)}
            >
              <PlusIcon />
            </Button>
            <Tooltip>Add column</Tooltip>
          </TooltipTrigger>
          {columnPosition.canDelete ? (
            <TooltipTrigger>
              <Button
                intent="outline"
                size="sq-xs"
                aria-label="Delete column"
                className={DELETE_BUTTON_CLASSNAME}
                preventFocusOnPress
                onPress={() => withCell(columnCellRef, $deleteTableColumnAtSelection)}
              >
                <TrashIcon />
              </Button>
              <Tooltip>Delete column</Tooltip>
            </TooltipTrigger>
          ) : null}
        </div>
      ) : null}
      {rowPosition ? (
        <div
          ref={rowActionsRef}
          className="fixed z-10 flex -translate-x-1/2 -translate-y-1/2 flex-col items-center gap-0.5"
          style={{ left: rowPosition.x, top: rowPosition.y }}
        >
          <TooltipTrigger>
            <Button
              intent="outline"
              size="sq-xs"
              aria-label="Add row"
              className={BUTTON_CLASSNAME}
              preventFocusOnPress
              onPress={() => withCell(rowCellRef, $insertTableRowAtSelection)}
            >
              <PlusIcon />
            </Button>
            <Tooltip>Add row</Tooltip>
          </TooltipTrigger>
          {rowPosition.canDelete ? (
            <TooltipTrigger>
              <Button
                intent="outline"
                size="sq-xs"
                aria-label="Delete row"
                className={DELETE_BUTTON_CLASSNAME}
                preventFocusOnPress
                onPress={() => withCell(rowCellRef, $deleteTableRowAtSelection)}
              >
                <TrashIcon />
              </Button>
              <Tooltip>Delete row</Tooltip>
            </TooltipTrigger>
          ) : null}
        </div>
      ) : null}
    </>,
    document.body,
  );
}

import { createPortal } from "react-dom";
import { useCallback, useEffect, useMemo, useState } from "react";

import type { TextNode } from "lexical";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import {
  LexicalTypeaheadMenuPlugin,
  MenuOption,
  type MenuTextMatch,
  useBasicTypeaheadTriggerMatch,
} from "@lexical/react/LexicalTypeaheadMenuPlugin";

import { UserIcon } from "@heroicons/react/16/solid";
import { twJoin } from "cn";

import { $createMentionNode } from "@/components/editor/nodes/mention-node";

const MAX_SUGGESTIONS = 5;

const PUNCTUATION = "\\.,\\+\\*\\?\\$\\@\\|#{}\\(\\)\\^\\-\\[\\]\\\\/!%'\"~=<>_:;";

const TRIGGERS = ["@"].join("");

const VALID_CHARS = "[^" + TRIGGERS + PUNCTUATION + "\\s]";

const VALID_JOINS = "(?:" + "\\.[ |$]|" + " |" + "[" + PUNCTUATION + "]|" + ")";

const LENGTH_LIMIT = 75;

const AtSignMentionsRegex = new RegExp(
  "(^|\\s|\\()(" +
    "[" +
    TRIGGERS +
    "]" +
    "((?:" +
    VALID_CHARS +
    VALID_JOINS +
    "){0," +
    LENGTH_LIMIT +
    "})" +
    ")$",
);

const ALIAS_LENGTH_LIMIT = 50;

const AtSignMentionsRegexAliasRegex = new RegExp(
  "(^|\\s|\\()(" +
    "[" +
    TRIGGERS +
    "]" +
    "((?:" +
    VALID_CHARS +
    "){0," +
    ALIAS_LENGTH_LIMIT +
    "})" +
    ")$",
);

const MENTIONS = [
  "Aayla Secura",
  "Admiral Gial Ackbar",
  "Ahsoka Tano",
  "Anakin Skywalker",
  "Asajj Ventress",
  "BB-8",
  "Bail Organa",
  "Beru Lars",
  "Boba Fett",
  "Bodhi Rook",
  "C-3PO",
  "Captain Phasma",
  "Captain Rex",
  "Cassian Andor",
  "Chewbacca",
  "Chirrut Îmwe",
  "Count Dooku",
  "Darth Maul",
  "Darth Vader",
  "Ezra Bridger",
  "Finn",
  "Galen Erso",
  "General Grievous",
  "Grand Moff Tarkin",
  "Greedo",
  "Han Solo",
  "Hera Syndulla",
  "Jabba the Hutt",
  "Jango Fett",
