  "Rey",
  "Rose Tico",
  "Sabine Wren",
  "Saw Gerrera",
  "Sheev Palpatine",
  "Shmi Skywalker",
  "Wedge Antilles",
  "Yoda",
];

const mentionsCache = new Map<string, string[] | null>();

const lookupService = {
  search(query: string, callback: (results: string[]) => void): void {
    setTimeout(() => {
      const results = MENTIONS.filter((mention) =>
        mention.toLowerCase().includes(query.toLowerCase()),
      );
      callback(results);
    }, 250);
  },
};

function useMentionLookupService(mentionString: string | null) {
  const [results, setResults] = useState<string[]>([]);

  useEffect(() => {
    if (mentionString === null) {
      setResults([]);
      return;
    }

    const cachedResults = mentionsCache.get(mentionString);
    if (cachedResults === null) {
      return;
    }
    if (cachedResults !== undefined) {
      setResults(cachedResults);
      return;
    }

    mentionsCache.set(mentionString, null);
    lookupService.search(mentionString, (newResults) => {
      mentionsCache.set(mentionString, newResults);
      setResults(newResults);
    });
  }, [mentionString]);

  return results;
}

function checkForAtSignMentions(text: string, minMatchLength: number): MenuTextMatch | null {
  let match = AtSignMentionsRegex.exec(text);

  if (match === null) {
    match = AtSignMentionsRegexAliasRegex.exec(text);
  }
  if (match !== null) {
    const maybeLeadingWhitespace = match[1];
    const matchingString = match[3];
    if (matchingString.length >= minMatchLength) {
      return {
        leadOffset: match.index + maybeLeadingWhitespace.length,
        matchingString,
        replaceableString: match[2],
      };
    }
  }
  return null;
}

class MentionTypeaheadOption extends MenuOption {
  name: string;

  constructor(name: string) {
    super(name);
    this.name = name;
  }
}

export function MentionPlugin() {
  const [editor] = useLexicalComposerContext();
  const [queryString, setQueryString] = useState<string | null>(null);

  const results = useMentionLookupService(queryString);

  const options = useMemo(
    () => results.slice(0, MAX_SUGGESTIONS).map((result) => new MentionTypeaheadOption(result)),
    [results],
  );

  const onSelectOption = useCallback(
    (option: MentionTypeaheadOption, nodeToReplace: TextNode | null, closeMenu: () => void) => {
      editor.update(() => {
        const mentionNode = $createMentionNode(option.name);
        if (nodeToReplace) {
          nodeToReplace.replace(mentionNode);
        }
        mentionNode.select();
        closeMenu();
      });
    },
    [editor],
  );

  const checkForSlashTriggerMatch = useBasicTypeaheadTriggerMatch("/", {
    minLength: 0,
  });

  const checkForMentionMatch = useCallback(
    (text: string) => {
      if (checkForSlashTriggerMatch(text, editor) !== null) {
        return null;
      }
      return checkForAtSignMentions(text, 1);
    },
    [checkForSlashTriggerMatch, editor],
  );

  return (
    <LexicalTypeaheadMenuPlugin<MentionTypeaheadOption>
      onQueryChange={setQueryString}
      onSelectOption={onSelectOption}
      triggerFn={checkForMentionMatch}
      options={options}
      menuRenderFn={(
        anchorElementRef,
        { selectedIndex, selectOptionAndCleanUp, setHighlightedIndex },
      ) =>
        anchorElementRef.current && options.length > 0
          ? createPortal(
              <div className="absolute inset-s-0 top-full z-50 -mt-4 w-56 rounded-lg bg-overlay text-overlay-foreground shadow-xs ring ring-muted-foreground/20 drop-shadow-xl dark:ring-border">
                <div
                  role="listbox"
                  className="scrollbar-thin flex max-h-64 flex-col gap-y-1 overflow-y-auto overscroll-contain p-1 sm:text-sm"
                >
                  {options.map((option, index) => (
                    <div
                      key={option.key}
                      ref={option.setRefElement}
                      role="option"
                      aria-selected={selectedIndex === index}
                      tabIndex={-1}
                      onMouseEnter={() => setHighlightedIndex(index)}
                      onMouseDown={(event) => event.preventDefault()}
                      onClick={() => selectOptionAndCleanUp(option)}
                      className={twJoin(
                        "flex cursor-default select-none items-center gap-x-2 rounded-md px-3 py-2 text-base/6 text-foreground outline-0 sm:px-2.5 sm:py-1.5 sm:text-sm/6",
                        selectedIndex === index && "bg-accent text-accent-foreground",
                      )}
                    >
                      <UserIcon className="size-4 shrink-0 text-muted-foreground" />
                      <span className="truncate">{option.name}</span>
                    </div>
                  ))}
                </div>
              </div>,
              anchorElementRef.current,
            )
          : null
      }
    />
  );
}

import { useEffect, useMemo, useState } from "react";

import {
  $createParagraphNode,
  $getRoot,
  $getSelection,
  $isElementNode,
  $isRangeSelection,
  COMMAND_PRIORITY_CRITICAL,
  type ElementNode,
  SELECTION_CHANGE_COMMAND,
} from "lexical";

import { getPeerDependencyFromEditor } from "@lexical/extension";
import {
  $isListNode,
  type CheckListExtension,
  INSERT_CHECK_LIST_COMMAND,
  INSERT_ORDERED_LIST_COMMAND,
  INSERT_UNORDERED_LIST_COMMAND,
  type ListExtension,
} from "@lexical/list";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { useLexicalEditable } from "@lexical/react/useLexicalEditable";
import {
  $createHeadingNode,
  $createQuoteNode,
  $isHeadingNode,
  $isQuoteNode,
} from "@lexical/rich-text";
import { $setBlocksType } from "@lexical/selection";
import { $findMatchingParent, mergeRegister } from "@lexical/utils";

import {
  Bars3BottomLeftIcon,
  ChatBubbleBottomCenterTextIcon,
  CheckCircleIcon,
  H1Icon,
  H2Icon,
  H3Icon,
  ListBulletIcon,
  NumberedListIcon,
} from "@heroicons/react/16/solid";

import { $getSelectedNode } from "@/components/editor/extensions/format-state";
import {
  ComboBox,
  ComboBoxContent,
  ComboBoxInput,
  ComboBoxItem,
  ComboBoxLabel,
} from "@/components/ui/combo-box";

const BLOCK_TYPES = ["paragraph", "h1", "h2", "h3", "number", "bullet", "check", "quote"] as const;

type BlockType = (typeof BLOCK_TYPES)[number];

const BLOCK_ITEMS: Record<
  BlockType,
  { label: string; icon: React.ComponentType<{ className?: string }> }
> = {
  paragraph: { label: "Paragraph", icon: Bars3BottomLeftIcon },
  h1: { label: "Heading 1", icon: H1Icon },
  h2: { label: "Heading 2", icon: H2Icon },
  h3: { label: "Heading 3", icon: H3Icon },
  number: { label: "Numbered list", icon: NumberedListIcon },
  bullet: { label: "Bulleted list", icon: ListBulletIcon },
  check: { label: "Check list", icon: CheckCircleIcon },
  quote: { label: "Quote", icon: ChatBubbleBottomCenterTextIcon },
};

function $getBlockType(): BlockType | null {
  const selection = $getSelection();
  if (!$isRangeSelection(selection)) {
    return null;
  }
  const node = $getSelectedNode(selection);
  const list = $findMatchingParent(node, $isListNode);
  if (list) {
    return list.getListType();
  }
  const element = $findMatchingParent(
    node,
    (parent): parent is ElementNode => $isElementNode(parent) && !parent.isInline(),
  );
  if ($isHeadingNode(element)) {
    const tag = element.getTag();
    return (BLOCK_TYPES as readonly string[]).includes(tag) ? (tag as BlockType) : "paragraph";
  }
  return $isQuoteNode(element) ? "quote" : "paragraph";
}

function $createBlockNode(blockType: BlockType) {
  switch (blockType) {
    case "h1":
    case "h2":
    case "h3":
      return $createHeadingNode(blockType);
    case "quote":
      return $createQuoteNode();
    default:
      return $createParagraphNode();
  }
}

function useBlockType(): BlockType {
  const [editor] = useLexicalComposerContext();
  const [blockType, setBlockType] = useState<BlockType>(
    () => editor.getEditorState().read($getBlockType) ?? "paragraph",
  );

  useEffect(() => {
    return mergeRegister(
      editor.registerUpdateListener(({ editorState }) => {
        const next = editorState.read($getBlockType);
        if (next) {
          setBlockType(next);
        }
      }),
      editor.registerCommand(
        SELECTION_CHANGE_COMMAND,
        () => {
          const next = $getBlockType();
          if (next) {
            setBlockType(next);
          }
          return false;
        },
        COMMAND_PRIORITY_CRITICAL,
      ),
    );
  }, [editor]);

  return blockType;
}

export function BlockFormatToolbarPlugin() {
  const [editor] = useLexicalComposerContext();
  const blockType = useBlockType();
  const isEditable = useLexicalEditable();

  const items = useMemo(() => {
    const hasList =
      getPeerDependencyFromEditor<typeof ListExtension>(editor, "@lexical/list/List") !== undefined;
    const hasCheckList =
      getPeerDependencyFromEditor<typeof CheckListExtension>(editor, "@lexical/list/CheckList") !==
      undefined;
    return BLOCK_TYPES.filter((item) => {
      if (item === "number" || item === "bullet") {
        return hasList;
      }
      if (item === "check") {
        return hasCheckList;
      }
      return true;
    });
  }, [editor]);

  const comboItems = useMemo(() => items.map((id) => ({ id })), [items]);

  return (
    <ComboBox
      aria-label="Block type"
      className="w-48"
      defaultItems={comboItems}
      value={blockType}
      isDisabled={!isEditable}
      onChange={(key) => {
        if (key === null) {
          return;
        }
        const value = key as BlockType;
        editor.update(() => {
          if (!$getSelection()) {
            $getRoot().selectEnd();
          }
        });
        switch (value) {
          case "number":
            editor.dispatchCommand(INSERT_ORDERED_LIST_COMMAND, undefined);
            return;
          case "bullet":
            editor.dispatchCommand(INSERT_UNORDERED_LIST_COMMAND, undefined);
            return;
          case "check":
            editor.dispatchCommand(INSERT_CHECK_LIST_COMMAND, undefined);
            return;
        }
        editor.update(() => {
          const selection = $getSelection() ?? $getRoot().selectEnd();
          $setBlocksType(selection, () => $createBlockNode(value));
        });
      }}
    >
      <ComboBoxInput className="h-7 py-0 sm:py-0 sm:text-xs" />
      <ComboBoxContent
        renderEmptyState={() => <span className="block p-2 text-sm text-muted-foreground">No matches</span>}
      >
        {(item: { id: BlockType }) => {
          const { label, icon: Icon } = BLOCK_ITEMS[item.id];
          return (
            <ComboBoxItem id={item.id} textValue={label}>
              <Icon />
              <ComboBoxLabel>{label}</ComboBoxLabel>
            </ComboBoxItem>
          );
        }}
      </ComboBoxContent>
    </ComboBox>
  );
}

import { useEffect, useState } from "react";

import { $getRoot, $isParagraphNode, CLEAR_EDITOR_COMMAND } from "lexical";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { useLexicalEditable } from "@lexical/react/useLexicalEditable";

import { BackspaceIcon, TrashIcon } from "@heroicons/react/16/solid";

