type IconComponent = React.ComponentType<{ className?: string }>;

// Heroicons has no glyphs for these formats, so draw them as SVG text. Being real
// <svg> elements, they get the same size and tone as the other toolbar icons.
const glyph = (children: React.ReactNode): IconComponent =>
  function Glyph({ className }) {
    return (
      <svg
        viewBox="0 0 16 16"
        fill="currentColor"
        fontSize={9}
        fontWeight={700}
        textAnchor="middle"
        aria-hidden="true"
        className={className}
      >
        {children}
      </svg>
    );
  };

const SubscriptIcon = glyph(
  <>
    <text x="6" y="10" fontSize={10}>
      x
    </text>
    <text x="12" y="13.5" fontSize={7}>
      2
    </text>
  </>,
);
const SuperscriptIcon = glyph(
  <>
    <text x="6" y="12" fontSize={10}>
      x
    </text>
    <text x="12" y="7" fontSize={7}>
      2
    </text>
  </>,
);
const UppercaseIcon = glyph(
  <text x="8" y="11.5" fontSize={10}>
    AA
  </text>,
);
const LowercaseIcon = glyph(
  <text x="8" y="11.5" fontSize={10}>
    aa
  </text>,
);
const TitleCaseIcon = glyph(
  <text x="8" y="11.5" fontSize={10}>
    Aa
  </text>,
);

const FORMAT_GROUPS: {
  format: TextFormatType;
  label: string;
  icon: IconComponent;
}[][] = [
  [
    { format: "bold", label: "Bold", icon: BoldIcon },
    { format: "italic", label: "Italic", icon: ItalicIcon },
    { format: "underline", label: "Underline", icon: UnderlineIcon },
    { format: "strikethrough", label: "Strikethrough", icon: StrikethroughIcon },
  ],
  [
    { format: "highlight", label: "Highlight", icon: PaintBrushIcon },
    { format: "code", label: "Inline code", icon: CodeBracketIcon },
  ],
  [
    { format: "subscript", label: "Subscript", icon: SubscriptIcon },
    { format: "superscript", label: "Superscript", icon: SuperscriptIcon },
  ],
  [
    { format: "uppercase", label: "Uppercase", icon: UppercaseIcon },
    { format: "lowercase", label: "Lowercase", icon: LowercaseIcon },
    { format: "capitalize", label: "Title case", icon: TitleCaseIcon },
  ],
];

function FormatToggleGroup({ items }: { items: (typeof FORMAT_GROUPS)[number] }) {
  const [editor] = useLexicalComposerContext();
  const formats = useFormatStateValue("formats");
  const isEditable = useLexicalEditable();
  return (
    <ToolbarGroup aria-label="Text formatting" isDisabled={!isEditable}>
      {items.map(({ format, label, icon: Icon }) => (
        <TooltipTrigger key={format}>
          <ToolbarItem
            size="sq-xs"
            aria-label={label}
            isSelected={formats.includes(format)}
            onChange={() => editor.dispatchCommand(FORMAT_TEXT_COMMAND, format)}
          >
            <Icon />
          </ToolbarItem>
          <Tooltip>{label}</Tooltip>
        </TooltipTrigger>
      ))}
    </ToolbarGroup>
  );
}

// The formats Markdown can write: **bold**, *italic*, ~~strikethrough~~ and `code`.
const MARKDOWN_FORMATS: TextFormatType[] = ["bold", "italic", "strikethrough", "code"];
const MARKDOWN_GROUP = FORMAT_GROUPS.flat().filter(({ format }) => MARKDOWN_FORMATS.includes(format));

export function TextFormatToolbarPlugin({
  formats = "all",
}: {
  formats?: "basic" | "markdown" | "all";
}) {
  const groups =
    formats === "basic"
      ? FORMAT_GROUPS.slice(0, 1)
      : formats === "markdown"
        ? [MARKDOWN_GROUP]
        : FORMAT_GROUPS;
  return (
    <>
      {groups.map((items, groupIndex) => (
        <Fragment key={groupIndex}>
          {groupIndex > 0 && <ToolbarSeparator />}
          <FormatToggleGroup items={items} />
        </Fragment>
      ))}
    </>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import { ChevronLeftIcon, ChevronRightIcon } from "@heroicons/react/16/solid";

import { cn } from "cn";

import { cx } from "@/lib/primitive";

import { Button } from "@/components/ui/button";
import { Toolbar as ToolbarPrimitive, type ToolbarProps } from "@/components/ui/toolbar";

const SCROLL_STEP = 0.75;

export function Toolbar({ className, ...props }: ToolbarProps) {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const getScroller = () => wrapperRef.current?.querySelector<HTMLElement>("[role=toolbar]") ?? null;
  const [overflow, setOverflow] = useState({ start: false, end: false });

  const update = useCallback(() => {
    const el = wrapperRef.current?.querySelector<HTMLElement>("[role=toolbar]");
    if (!el) return;
    const max = el.scrollWidth - el.clientWidth;
    const offset = Math.abs(el.scrollLeft);
    setOverflow({ start: offset > 1, end: offset < max - 1 });
  }, []);

  useEffect(() => {
    const el = wrapperRef.current?.querySelector<HTMLElement>("[role=toolbar]");
    if (!el) return;

    update();
    const observer = new ResizeObserver(update);
    observer.observe(el);
    for (const child of Array.from(el.children)) observer.observe(child);
    el.addEventListener("scroll", update, { passive: true });

    // Let a vertical mouse wheel scroll the toolbar sideways while it can still move.
    const onWheel = (event: WheelEvent) => {
      if (Math.abs(event.deltaY) <= Math.abs(event.deltaX)) return;
      const max = el.scrollWidth - el.clientWidth;
      const atStart = event.deltaY < 0 && el.scrollLeft <= 0;
      const atEnd = event.deltaY > 0 && Math.abs(el.scrollLeft) >= max - 1;
      if (max <= 0 || atStart || atEnd) return;
      event.preventDefault();
      el.scrollLeft += event.deltaY;
    };
    el.addEventListener("wheel", onWheel, { passive: false });

    return () => {
      observer.disconnect();
      el.removeEventListener("scroll", update);
      el.removeEventListener("wheel", onWheel);
    };
  }, [update]);

  const scroll = (direction: -1 | 1) => {
    const el = getScroller();
    if (!el) return;
    const rtl = getComputedStyle(el).direction === "rtl" ? -1 : 1;
    el.scrollBy({
      left: direction * rtl * el.clientWidth * SCROLL_STEP,
      behavior: "smooth",
    });
  };

  return (
    <div ref={wrapperRef} className="relative w-full shrink-0">
      <ToolbarPrimitive
        aria-label="Formatting"
        {...props}
        className={cx(
          "w-full flex-nowrap gap-1 overflow-x-auto overscroll-x-contain scroll-px-14 rounded-none border-b border-border bg-background p-1.5 inset-ring-0 *:shrink-0",
          className,
        )}
      />
      <ScrollEdge side="start" visible={overflow.start} onPress={() => scroll(-1)} />
      <ScrollEdge side="end" visible={overflow.end} onPress={() => scroll(1)} />
    </div>
  );
}

function ScrollEdge({
  side,
  visible,
  onPress,
}: {
  side: "start" | "end";
  visible: boolean;
  onPress: () => void;
}) {
  const isStart = side === "start";
  const Icon = isStart ? ChevronLeftIcon : ChevronRightIcon;
  return (
    // The padding matches the toolbar's p-1.5, so the button sits exactly where a control
    // would. The fade only softens the controls that scroll underneath it.
    <div
      aria-hidden
      className={cn(
        "pointer-events-none absolute top-0 bottom-px z-10 flex w-14 items-center from-background via-background via-72% to-transparent transition-opacity duration-150",
        isStart
          ? "inset-s-0 justify-start ps-1.5 bg-linear-to-r rtl:bg-linear-to-l"
          : "inset-e-0 justify-end pe-1.5 bg-linear-to-l rtl:bg-linear-to-r",
        visible ? "opacity-100" : "opacity-0",
      )}
    >
      <Button
        intent="outline"
        size="sq-xs"
        excludeFromTabOrder
        isDisabled={!visible}
        aria-label={isStart ? "Scroll toolbar left" : "Scroll toolbar right"}
        onPress={onPress}
        className={cn("[--btn-bg:var(--color-background)]", visible && "pointer-events-auto")}
      >
        <Icon className="rtl:rotate-180" />
      </Button>
    </div>
  );
}

